import re

_PART = re.compile(r"(\d+)([hms])")


def parse_duration(text):
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    units = {"h": 3600, "m": 60, "s": 1}
    pos, total = 0, 0
    while pos < len(s):
        m = _PART.match(s, pos)
        if not m:
            raise ValueError("bad duration: %r" % text)
        total += int(m.group(1)) * units[m.group(2)]
        pos = m.end()
        while pos < len(s) and s[pos] == " ":
            pos += 1
    return total
EOF

