TOKEN = re.compile(r"\s*(\d+\.?\d*|[-+*/()])")


def tokenize(s):
    pos, out = 0, []
    s = s.strip()
    while pos < len(s):
        m = TOKEN.match(s, pos)
        if not m:
            raise ValueError("bad character at %d" % pos)
        out.append(m.group(1))
        pos = m.end()
    return out


def evaluate(s):
    value, rest = expr(tokenize(s))
    if rest:
        raise ValueError("trailing tokens")
    return value


def expr(t):
    value, t = term(t)
    while t and t[0] in "+-":
        op = t[0]
        rhs, t = term(t[1:])
        value = value + rhs if op == "+" else value - rhs
    return value, t


def term(t):
    value, t = factor(t)
    while t and t[0] in "*/":
        op = t[0]
        rhs, t = factor(t[1:])
        value = value * rhs if op == "*" else value / rhs
    return value, t


def factor(t):
    if not t:
        raise ValueError("unexpected end")
    tok = t[0]
    if tok == "-":
        value, t = factor(t[1:])
        return -value, t
    if tok == "(":
        value, t = expr(t[1:])
        if not t or t[0] != ")":
            raise ValueError("missing )")
        return value, t[1:]
    return float(tok), t[1:]
